// writePNGTemp generates a tiny valid PNG (w x h) in a temp dir and returns its
// path. Thin wrapper over writePNG (defined in exiftool_test.go) so the
// real-exiftool Convert test gets a deterministic fixture without a committed binary.
func writePNGTemp(t *testing.T, w, h int) string {
	t.Helper()
	p := filepath.Join(t.TempDir(), "base.png")
	writePNG(t, p, w, h)
	return p
}

// matchReq builds a MatchRequest whose item carries the parsed base fields the
// way base-scanner + scan stamp them (relative_path/extension/absolute_path), and
// the given module_type. Test helper.
func matchReq(moduleType string, parsed map[string]any) *metadatav1.MatchRequest {
	st, _ := structpb.NewStruct(parsed)
	return &metadatav1.MatchRequest{
		Item:       &scannerv1.IdentifyResult{Parsed: st},
		ModuleType: moduleType,
	}
}

// strField reads a string field from a Struct ("" if absent). Test helper.
func strField(s *structpb.Struct, key string) string {
	return s.GetFields()[key].GetStringValue()
}

// TestMatch is the table test for enricherImpl.Match (B02): applies iff the item
// is an image (module_type=="image" OR the lowercased extension is an image
// extension), and on applies the Query carries absolute_path (the file-location
// channel D-6) + a format hint. Non-image items are skipped (never an error).
func TestMatch(t *testing.T) {
	tests := []struct {
		name       string
		moduleType string
		parsed     map[string]any
		applies    bool
		wantFmt    string // "" => don't assert
		wantAbs    string // expected absolute_path in Query
	}{
		{
			name:       "image_module_type_jpg",
			moduleType: "image",
			parsed:     map[string]any{"relative_path": "vacation/IMG.jpg", "extension": ".jpg", "absolute_path": "/lib/vacation/IMG.jpg"},
			applies:    true,
			wantFmt:    "jpeg",
			wantAbs:    "/lib/vacation/IMG.jpg",
		},
		{
			// B02: image by EXTENSION alone (module_type empty) still applies.
			name:       "image_by_extension_only",
			moduleType: "",
			parsed:     map[string]any{"extension": ".png", "absolute_path": "/lib/a.png"},
			applies:    true,
			wantFmt:    "png",
			wantAbs:    "/lib/a.png",
		},
		{
			name:       "heic_applies",
			moduleType: "image",
			parsed:     map[string]any{"extension": ".heic", "absolute_path": "/lib/x.heic"},
			applies:    true,
			wantFmt:    "heic",
			wantAbs:    "/lib/x.heic",
		},
		{
			// B08-adjacent: a Cyrillic-stemmed .jpg is discovered (ASCII ext only).
			name:       "cyrillic_stem_jpg",
			moduleType: "image",
			parsed:     map[string]any{"relative_path": "Фото.jpg", "extension": ".jpg", "absolute_path": "/lib/Фото.jpg"},
			applies:    true,
			wantFmt:    "jpeg",
			wantAbs:    "/lib/Фото.jpg",
		},
		{
			// B02: a TV .mkv item does NOT apply (skipped, never an error).
			name:       "tv_mkv_not_applies",
			moduleType: "tv",
			parsed:     map[string]any{"relative_path": "Show S01E01.mkv", "extension": ".mkv"},
			applies:    false,
		},
		{
			// No module_type and a non-image extension -> not an image.
			name:       "nfo_not_applies",
			moduleType: "",
			parsed:     map[string]any{"extension": ".nfo"},
			applies:    false,
		},
	}
	p := &enricherImpl{}
	for _, tc := range tests {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			res, err := p.Match(context.Background(), matchReq(tc.moduleType, tc.parsed))
			if err != nil {
				t.Fatalf("Match: %v", err)
			}
			if res.GetApplies() != tc.applies {
				t.Fatalf("applies = %v, want %v (reason=%q)", res.GetApplies(), tc.applies, res.GetReason())
			}
			if !tc.applies {
				return
			}
			q := res.GetQuery()
			if got := strField(q, "absolute_path"); got != tc.wantAbs {
				t.Errorf("Query.absolute_path = %q, want %q", got, tc.wantAbs)
			}
			if tc.wantFmt != "" {
				if got := strField(q, "format"); got != tc.wantFmt {
					t.Errorf("Query.format = %q, want %q", got, tc.wantFmt)
				}
			}
			if c := res.GetConfidence(); c != 1.0 {
				t.Errorf("Confidence = %v, want 1.0", c)
			}
		})
	}
}

// TestBuildRequest asserts BuildRequest is a nop returning an empty RequestSpec
// (B03): the local EXIF "fetch" is the file read done in Convert; there is no
// external fetch in B2.
func TestBuildRequest(t *testing.T) {
	p := &enricherImpl{}
	res, err := p.BuildRequest(context.Background(), &metadatav1.BuildRequestRequest{})
	if err != nil {
		t.Fatalf("BuildRequest: %v", err)
	}
	if res.GetSpec() == nil {
		t.Fatal("BuildRequest spec nil, want an empty RequestSpec")
	}
}

// TestMerge asserts INV-namespace-write (B05): Merge writes ONLY the
// sources["image-enricher"] namespace — no other top-level key, no foreign
// source, never _provenance/_view/_stages — and returns one view binding per
// field with source "image-enricher".
func TestMerge(t *testing.T) {
	p := &enricherImpl{}
	incoming, _ := structpb.NewStruct(map[string]any{
		"width":  float64(4000),
		"height": float64(3000),
		"format": "jpeg",
		"make":   "Apple",
	})
	res, err := p.Merge(context.Background(), &metadatav1.MergeRequest{Incoming: incoming, PluginId: pluginID})
	if err != nil {
		t.Fatalf("Merge: %v", err)
	}
	data := res.GetDocument().GetData().AsMap()
	if len(data) != 1 {
		t.Fatalf("document top-level keys = %v, want exactly {sources} (INV-namespace-write)", data)
	}
	sources, ok := data["sources"].(map[string]any)
	if !ok {
		t.Fatalf("document has no sources map: %v", data)
	}
	if len(sources) != 1 {
		t.Fatalf("sources namespaces = %v, want exactly {image-enricher}", sources)
	}
	ns, _ := sources[pluginID].(map[string]any)
	if got := ns["format"]; got != "jpeg" {
		t.Errorf("sources.image-enricher.format = %v, want jpeg", got)
	}
	// INV-namespace-write: the core-owned namespaces must NOT appear.
	for _, forbidden := range []string{"_provenance", "_view", "_stages"} {
		if _, leaked := data[forbidden]; leaked {
			t.Errorf("document leaked core-owned key %q (INV-namespace-write)", forbidden)
		}
	}
	view := res.GetView()
	if len(view) != len(ns) {
		t.Fatalf("view bindings = %d, want one per metadata field (%d)", len(view), len(ns))
	}
	for _, vb := range view {
		if vb.GetSource() != pluginID {
			t.Errorf("view[%q].source = %q, want %q", vb.GetFieldPath(), vb.GetSource(), pluginID)
		}
	}
}

// TestConvert_SoftFailMissingExiftool is the soft-fail unit test for Convert
// (B06/B07): when exiftool is NOT on PATH, Convert returns EMPTY metadata + a
// non-empty Warnings entry and no error (NOT ConvertResult.Error) -> the empty
// namespace -> B1 no_data terminal. Covered regardless of exiftool install.
func TestConvert_SoftFailMissingExiftool(t *testing.T) {
	if _, err := exec.LookPath(exiftoolBin); err == nil {
		t.Skip("exiftool is present; the missing-binary soft-fail path is not exercised here")
	}
	p := &enricherImpl{}
	query, _ := structpb.NewStruct(map[string]any{"absolute_path": "/nonexistent/IMG.jpg"})
	res, err := p.Convert(context.Background(), &metadatav1.ConvertRequest{Query: query})
	if err != nil {
		t.Fatalf("Convert: unexpected error %v (exiftool-missing is a SOFT fail, not a gRPC error)", err)
	}
	if res.GetMetadata() != nil && len(res.GetMetadata().GetFields()) != 0 {
		t.Fatalf("Convert metadata = %v, want empty when exiftool is missing", res.GetMetadata().AsMap())
	}
	if res.GetError() != nil {
		t.Fatalf("ConvertResult.Error = %v, want nil (soft-fail uses Warnings, not Error)", res.GetError())
	}
	if len(res.GetWarnings()) == 0 {
		t.Fatal("Convert warnings empty, want a soft-fail reason")
	}
}

// TestConvert_RealPNG proves B08 (a valid EXIF-less image yields {width,height,
// format} so it is a clean success, not a spurious no_data) and that Convert
// populates per-field provenance hints. Gated on LookPath("exiftool") — skips
// cleanly when exiftool is absent (soft-fail path covered above).
func TestConvert_RealPNG(t *testing.T) {
	if _, err := exec.LookPath(exiftoolBin); err != nil {
		t.Skip("exiftool not on PATH")
	}
	pngPath := writePNGTemp(t, 9, 5)
	p := &enricherImpl{}
	query, _ := structpb.NewStruct(map[string]any{"absolute_path": pngPath})
	res, err := p.Convert(context.Background(), &metadatav1.ConvertRequest{Query: query})
	if err != nil {
		t.Fatalf("Convert: %v", err)
	}
	meta := res.GetMetadata()
	if meta == nil {
		t.Fatal("Convert metadata nil, want non-empty for a valid PNG (B08)")
	}
	for _, key := range []string{"width", "height", "format"} {
		if _, ok := meta.GetFields()[key]; !ok {
			t.Errorf("metadata missing %q (got=%v) — a valid image must contribute it (B08)", key, meta.AsMap())
		}
	}
	if got := strField(meta, "format"); got != "png" {
		t.Errorf("metadata format = %q, want png", got)
	}
	if len(res.GetWarnings()) != 0 {
		t.Errorf("Convert warnings = %v, want none for a valid image", res.GetWarnings())
	}
	prov := res.GetProvenance()
	if len(prov) == 0 {
		t.Fatal("provenance hint map empty, want one entry per metadata field")
	}
	for field, pr := range prov {
		if pr.GetPluginId() != pluginID {
			t.Errorf("provenance[%q].plugin_id = %q, want %q", field, pr.GetPluginId(), pluginID)
		}
	}
}
